<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<image :src="getFullUrl(art.image)" mode="aspectFill" class="top-img"></image>
		<scroll-view scroll-y="true" class="scroll">
			<view class="info">
				<view class="tit-text">{{art.gs_name}}</view>
				<view class="title-text">公司概况</view>
				<view class="info-items">
					<view class="info-item">
						<text class="left-text">成立时间</text>
						<text class="right-text">{{art.cl_time}}</text>
					</view>
					<view class="info-item">
						<text class="left-text">公司规模</text>
						<text class="right-text">{{art.gs_gm}}</text>
					</view>
					<view class="info-item">
						<text class="left-text">主营业务</text>
						<text class="right-text">{{art.zy_yw}}</text>
					</view>
				</view>
				<view class="content">
					<view class="title-text">公司介绍</view>
					<view class="content-text" v-html="art.content"></view>
				</view>
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				art:{}
			}
		},
		onLoad(e) {
			_this = this;
			this.get_wz_xq()
		},
		methods: {
			async get_wz_xq() {
				const params = {
					id:3,
					is_http:1,
				}
				const data = await _this.$post('port/xieyi_xq', params)
				if (data.code == 200) {
					_this.art = data.result.art
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			}
		}
	}
</script>

